          "id": "T04_3-code",
          "type": "code",
          "language": "cpp",
          "standard": "c++17",
          "caption": "Double Hashing Hash Table with Dynamic Rehashing in C++",
          "source": "#include <vector>\n#include <optional>\n#include <cstddef>\n#include <cstdint>\n\nenum class EntryState { EMPTY, OCCUPIED, DELETED };\n\nstruct HashSlot {\n    int key;\n    int value;\n    EntryState state = EntryState::EMPTY;\n};\n\nclass DoubleHashMap {\nprivate:\n    std::vector<HashSlot> table;\n    size_t capacity;\n    size_t count = 0;\n\n    static bool is_prime(size_t n) {\n        if (n < 2) return false;\n        if (n == 2 || n == 3) return true;\n        if (n % 2 == 0 || n % 3 == 0) return false;\n        for (size_t d = 5; d <= n / d; d += 6) {\n            if (n % d == 0 || n % (d + 2) == 0) return false;\n        }\n        return true;\n    }\n\n    static size_t next_prime(size_t n) {\n        if (n <= 2) return 2;\n        if (n % 2 == 0) n++;\n        while (!is_prime(n)) {\n            n += 2;\n        }\n        return n;\n    }\n\n    // Unsigned cast safely handles negative numbers including INT_MIN without negation overflow UB\n    size_t h1(int k) const {\n        return static_cast<size_t>(static_cast<uint32_t>(k)) % capacity;\n    }\n\n    // Step size is guaranteed coprime to prime capacity and in range [1, capacity - 1]\n    size_t h2(int k) const {\n        if (capacity <= 2) return 1;\n        size_t step = 1 + (static_cast<size_t>(static_cast<uint32_t>(k)) % (capacity - 1));\n        return step;\n    }\n\npublic:\n    explicit DoubleHashMap(size_t cap = 7) {\n        capacity = (is_prime(cap) && cap >= 3) ? cap : next_prime(cap < 3 ? 3 : cap);\n        table.resize(capacity);\n    }\n\n    bool insert(int key, int val) {\n        // Step 1: Scan probe chain to check if key already exists (pure update does not grow table)\n        size_t idx = h1(key);\n        size_t step = h2(key);\n        int first_deleted = -1;\n\n        for (size_t i = 0; i < capacity; ++i) {\n            size_t probe = (idx + i * step) % capacity;\n            if (table[probe].state == EntryState::OCCUPIED) {\n                if (table[probe].key == key) {\n                    table[probe].value = val;\n                    return true;\n                }\n            } else if (table[probe].state == EntryState::DELETED) {\n                if (first_deleted == -1) {\n                    first_deleted = static_cast<int>(probe);\n                }\n            } else { // EMPTY slot: key definitely does not exist in table\n                break;\n            }\n        }\n\n        // Step 2: Key does not exist; check if rehash is needed before inserting new key\n        if ((count + 1) * 10 >= capacity * 7) {\n            rehash(next_prime(capacity * 2));\n            idx = h1(key);\n            step = h2(key);\n            first_deleted = -1;\n            for (size_t i = 0; i < capacity; ++i) {\n                size_t probe = (idx + i * step) % capacity;\n                if (table[probe].state == EntryState::OCCUPIED) {\n                    if (table[probe].key == key) {\n                        table[probe].value = val;\n                        return true;\n                    }\n                } else if (table[probe].state == EntryState::DELETED) {\n                    if (first_deleted == -1) first_deleted = static_cast<int>(probe);\n                } else {\n                    break;\n                }\n            }\n        }\n\n        // Step 3: Insert new key into first_deleted if available, else probe until free slot\n        if (first_deleted != -1) {\n            table[first_deleted] = {key, val, EntryState::OCCUPIED};\n            count++;\n            return true;\n        }\n\n        for (size_t i = 0; i < capacity; ++i) {\n            size_t probe = (idx + i * step) % capacity;\n            if (table[probe].state != EntryState::OCCUPIED) {\n                table[probe] = {key, val, EntryState::OCCUPIED};\n                count++;\n                return true;\n            }\n        }\n\n        return false;\n    }\n\n    void rehash(size_t new_cap) {\n        size_t prime_cap = is_prime(new_cap) ? new_cap : next_prime(new_cap);\n        std::vector<HashSlot> old_table = std::move(table);\n        capacity = prime_cap;\n        table = std::vector<HashSlot>(capacity);\n        count = 0;\n        for (const auto& slot : old_table) {\n            if (slot.state == EntryState::OCCUPIED) {\n                insert(slot.key, slot.value);\n            }\n        }\n    }\n\n    size_t size() const { return count; }\n    size_t getCapacity() const { return capacity; }\n};"
